    let score = 0; let answered = 0;
    const container = document.getElementById('quiz-container');
    const shuffled = questions.sort(() => Math.random() - 0.5);

    shuffled.forEach((item, idx) => {
        const card = document.createElement('div');
        card.className = 'question-card';
        card.innerHTML = `<strong>${idx+1}. ${item.q}</strong><div class="options" id="opt-${idx}"></div>`;
        container.appendChild(card);
        const options = item.a.map((t,i)=>({text:t, orig:i}))
.sort(()=>Math.random()-0.5);

options.forEach((opt) => {
            const btn = document.createElement('div');
            btn.className = 'option';
            btn.innerText = opt.text;
            btn.onclick = () => {
                const parent = document.getElementById(`opt-${idx}`);
                if (opt.orig === item.correct) { btn.classList.add('correct'); score++; }
                else { btn.classList.add('wrong'); }
                Array.from(parent.children).forEach(c => c.classList.add('disabled'));
                answered++;
                document.getElementById('ans-count').innerText = answered;
                document.getElementById('score').innerText = score;
                document.getElementById('percent').innerText =
                Math.round((score/questions.length)*100);
            };
            document.getElementById(`opt-${idx}`).appendChild(btn);
        });
    });
    document.querySelectorAll("#total-q").forEach(e=>{
    e.innerText = questions.length;
});
